using UnityEngine; namespace SkiStation { public class WeatherDebugUI:MonoBehaviour {bool show;void Update(){if(Input.GetKeyDown(KeyCode.F4))show=!show;}void OnGUI(){if(!show||WeatherRuntime.I==null)return;var w=WeatherRuntime.I.Current;GUI.Box(new Rect(12,150,330,105),"METEO — F4");GUI.Label(new Rect(25,178,300,22),$"État : {w.condition}");GUI.Label(new Rect(25,198,300,22),$"Température : {w.temperatureC:0.0} °C");GUI.Label(new Rect(25,218,300,22),$"Vent : {w.windKmh:0} km/h   Visibilité : {w.visibility:P0}");}}}
